sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var retry_cnt = gs.getProperty("x_hsb11_mss_c_ghss.ghss_retry_count");

    var ghssOutbound = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
    //ghssOutbound.addQuery('retry_count',retry_cnt);
    ghssOutbound.addQuery('sn_task', current.sys_id);
    ghssOutbound.query();
    if (ghssOutbound.next()) {
        if (current.state == "4" && ghssOutbound.retry_count == retry_cnt) {

            // Calls the rest message configured to send widget failture details to ITID instance and creates an Event

            var failureDescription = encodeURIComponent("HSBC MSS iQube Widget failure, details of the error are as below ServiceNow Reference: " + current.number + " Timestamp : " + ghssOutbound.response_date + "Error code: " + ghssOutbound.response_code + "Error Body: " + current.response_body);
            var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_EventLayer');
        }
    }

})(current, previous);
